#[derive(Deserialize)]
pub struct ApiRequest {
    pub project: String,
    #[serde(default)]
    pub verify: bool,
    #[serde(default)]
    pub check: bool,
    pub ops: Vec<ApiOp>,
}

#[derive(Deserialize)]
#[serde(tag = "op", content = "args")]
pub enum ApiOp {
    RenameSymbol { old: String, new: String },
    MoveSymbol { symbol_id: String, new_module_path: String },
    RenameModule { old_module_path: String, new_name: String },
    RenameDir { old_dir: String, new_dir: String },
    Help,
    ListOps,
    ListSymbols,
    GetSymbol { symbol_id: String },
    PreviewRename,
    CheckErrors,
    DeleteSymbol { symbol_id: String },
    InlineModule { module_path: String },
    ExtractModule { symbol_id: String, target_file: String },
    SuggestRenames { batch_size: Option<usize>, model: Option<String> },
    ApplySuggestions { suggestions: Vec<(String, String)> },
}

#[derive(Serialize)]
pub struct ApiResult {
    pub op: String,
    pub status: String,
    pub detail: Option<String>,
    pub data: Option<serde_json::Value>,
}

pub fn dispatch(editor: &mut ProjectEditor, op: &ApiOp) -> ApiResult {
    match op {
        ApiOp::RenameSymbol { old, new } => {
            let new_ident = match normalize_new_ident(new) {
                Ok(v) => v,
                Err(e) => {
                    return ApiResult {
                        op: "RenameSymbol".into(),
                        status: "error".into(),
                        detail: Some(e),
                        data: None,
                    }
                }
            };
            match editor.queue(
                old,
                NodeOp::MutateField {
                    handle: match editor.synthetic_handle_from_symbol_id(old) {
                        Ok(handle) => handle,
                        Err(e) => {
                            return ApiResult {
                                op: "RenameSymbol".into(),
                                status: "error".into(),
                                detail: Some(e.to_string()),
                                data: None,
                            }
                        }
                    },
                    mutation: FieldMutation::RenameIdent(new_ident),
                },
            ) {
            Ok(_) => ApiResult {
                op: "RenameSymbol".into(),
                status: "queued".into(),
                detail: None,
                data: None,
            },
            Err(e) => ApiResult {
                op: "RenameSymbol".into(),
                status: "error".into(),
                detail: Some(e.to_string()),
                data: None,
            },
            }
        }
        ApiOp::MoveSymbol {
            symbol_id,
            new_module_path,
        } => match editor.queue(
            symbol_id,
            NodeOp::MoveSymbol {
                handle: match editor.synthetic_handle_from_symbol_id(symbol_id) {
                    Ok(handle) => handle,
                    Err(e) => {
                        return ApiResult {
                            op: "MoveSymbol".into(),
                            status: "error".into(),
                            detail: Some(e.to_string()),
                            data: None,
                        }
                    }
                },
                symbol_id: symbol_id.clone(),
                new_module_path: new_module_path.clone(),
                new_crate: None,
            },
        ) {
            Ok(_) => ApiResult {
                op: "MoveSymbol".into(),
                status: "queued".into(),
                detail: None,
                data: None,
            },
            Err(e) => ApiResult {
                op: "MoveSymbol".into(),
                status: "error".into(),
                detail: Some(e.to_string()),
                data: None,
            },
        },
        ApiOp::RenameModule {
            old_module_path,
            new_name,
        } => {
            editor.queue_module_rename(old_module_path, new_name);
            ApiResult {
                op: "RenameModule".into(),
                status: "queued".into(),
                detail: None,
                data: None,
            }
        }
        ApiOp::RenameDir { old_dir, new_dir } => {
            editor.queue_directory_rename(&PathBuf::from(old_dir), &PathBuf::from(new_dir));
            ApiResult {
                op: "RenameDir".into(),
                status: "queued".into(),
                detail: None,
                data: None,
            }
        }
        ApiOp::Help | ApiOp::ListOps => {
            let ops = vec![
                "RenameSymbol",
                "MoveSymbol",
                "RenameModule",
                "RenameDir",
                "ListSymbols",
                "GetSymbol",
                "PreviewRename",
                "CheckErrors",
                "DeleteSymbol",
                "InlineModule",
                "ExtractModule",
                "SuggestRenames",
                "ApplySuggestions",
                "Help",
                "ListOps",
            ];
            let flags = serde_json::json!({
                "verify": "bool (default false)",
                "check": "bool (default false)"
            });
            ApiResult {
                op: match op {
                    ApiOp::Help => "Help",
                    _ => "ListOps",
                }
                .into(),
                status: "ok".into(),
                detail: None,
                data: Some(serde_json::json!({ "ops": ops, "flags": flags })),
            }
        }
        ApiOp::ListSymbols => {
            let data = editor
                .symbol_catalog()
                .into_iter()
                .map(|(id, kind)| serde_json::json!({ "symbol_id": id, "kind": kind }))
                .collect::<Vec<_>>();
            ApiResult {
                op: "ListSymbols".into(),
                status: "ok".into(),
                detail: None,
                data: Some(serde_json::Value::Array(data)),
            }
        }
        ApiOp::GetSymbol { symbol_id } => match editor.synthetic_handle_from_symbol_id(symbol_id) {
            Ok(handle) => ApiResult {
                op: "GetSymbol".into(),
                status: "ok".into(),
                detail: None,
                data: Some(serde_json::json!({
                    "file": handle.file,
                    "module_path": handle.module_path,
                    "name": handle.name,
                    "kind": format!("{:?}", handle.kind),
                })),
            },
            Err(e) => ApiResult {
                op: "GetSymbol".into(),
                status: "error".into(),
                detail: Some(e.to_string()),
                data: None,
            },
        },
        ApiOp::PreviewRename => match editor.preview() {
            Ok(diff) => ApiResult {
                op: "PreviewRename".into(),
                status: "ok".into(),
                detail: None,
                data: Some(serde_json::Value::String(diff)),
            },
            Err(e) => ApiResult {
                op: "PreviewRename".into(),
                status: "error".into(),
                detail: Some(e.to_string()),
                data: None,
            },
        },
        ApiOp::CheckErrors => ApiResult {
            op: "CheckErrors".into(),
            status: "unsupported".into(),
            detail: Some("CheckErrors is handled at the request level; use check=true".into()),
            data: None,
        },
        ApiOp::DeleteSymbol { symbol_id } => {
            let handle = match editor.synthetic_handle_from_symbol_id(symbol_id) {
                Ok(handle) => handle,
                Err(e) => {
                    return ApiResult {
                        op: "DeleteSymbol".into(),
                        status: "error".into(),
                        detail: Some(e.to_string()),
                        data: None,
                    }
                }
            };
            match editor.queue(
                symbol_id,
                NodeOp::DeleteSymbol {
                    handle,
                    symbol_id: symbol_id.clone(),
                },
            ) {
                Ok(_) => ApiResult {
                    op: "DeleteSymbol".into(),
                    status: "queued".into(),
                    detail: None,
                    data: None,
                },
                Err(e) => ApiResult {
                    op: "DeleteSymbol".into(),
                    status: "error".into(),
                    detail: Some(e.to_string()),
                    data: None,
                },
            }
        }
        ApiOp::InlineModule { .. } => ApiResult {
            op: "InlineModule".into(),
            status: "unsupported".into(),
            detail: Some("InlineModule not implemented".into()),
            data: None,
        },
        ApiOp::ExtractModule { .. } => ApiResult {
            op: "ExtractModule".into(),
            status: "unsupported".into(),
            detail: Some("ExtractModule not implemented".into()),
            data: None,
        },
        ApiOp::SuggestRenames { .. } => ApiResult {
            op: "SuggestRenames".into(),
            status: "unsupported".into(),
            detail: Some("SuggestRenames pipeline removed; not implemented".into()),
            data: None,
        },
        ApiOp::ApplySuggestions { suggestions } => {
            let mut failures = Vec::new();
            for (old, new) in suggestions {
                let new_ident = match normalize_new_ident(new) {
                    Ok(v) => v,
                    Err(e) => {
                        failures.push(format!("{old}: {e}"));
                        continue;
                    }
                };
                let handle = match editor.synthetic_handle_from_symbol_id(old) {
                    Ok(handle) => handle,
                    Err(e) => {
                        failures.push(format!("{old}: {e}"));
                        continue;
                    }
                };
                let op = NodeOp::MutateField {
                    handle,
                    mutation: FieldMutation::RenameIdent(new_ident),
                };
                if let Err(e) = editor.queue(old, op) {
                    failures.push(format!("{old}: {e}"));
                }
            }
            if failures.is_empty() {
                ApiResult {
                    op: "ApplySuggestions".into(),
                    status: "queued".into(),
                    detail: None,
                    data: None,
                }
            } else {
                ApiResult {
                    op: "ApplySuggestions".into(),
                    status: "partial".into(),
                    detail: Some(failures.join("; ")),
                    data: None,
                }
            }
        }
    }
}

fn normalize_new_ident(new_name: &str) -> Result<String, String> {
    if !new_name.contains("::") {
        return Err("new name must be a full path like crate::module::Type".to_string());
    }
    Ok(new_name
        .rsplit("::")
        .next()
        .unwrap_or(new_name)
        .to_string())
}

use serde_json::json;
use std::collections::BTreeMap;
use std::path::Path;
use std::process::Command;

#[derive(serde::Serialize)]
pub struct CargoCheckJson {
    pub diagnostics: Vec<serde_json::Value>,
    pub success: bool,
}

pub fn run_cargo_check_json(project: &Path) -> Result<CargoCheckJson, Box<dyn std::error::Error>> {
    let mut cmd = Command::new("cargo");
    cmd.arg("check").arg("--message-format=json").current_dir(project);
    let output = cmd.output()?;
    let success = output.status.success();
    let mut diagnostics = Vec::new();
    for line in String::from_utf8_lossy(&output.stdout).lines() {
        if let Ok(value) = serde_json::from_str::<serde_json::Value>(line) {
            if value.get("reason").and_then(|v| v.as_str()) == Some("compiler-message") {
                if let Some(message) = value.get("message") {
                    diagnostics.push(message.clone());
                }
                continue;
            }
            // analysis_capture may emit raw rustc JSON diagnostics (no "reason")
            if let Some(message) = value.get("message") {
                if message.is_object() {
                    diagnostics.push(message.clone());
                    continue;
                }
            }
            if value.get("level").is_some() && value.get("message").is_some() {
                diagnostics.push(value.clone());
            }
        }
    }
    if diagnostics.is_empty() && !success {
        diagnostics.push(json!({
            "level": "error",
            "code": { "code": "unknown" },
            "message": "cargo check failed without JSON diagnostics"
        }));
    }
    // keep diagnostics from this cargo check only (do not read analysis/errors.json)
    Ok(CargoCheckJson { diagnostics, success })
}

pub fn accumulate_error_counts_json(messages: &[serde_json::Value], counts: &mut BTreeMap<String, usize>) {
    for msg in messages {
        if msg.get("level").and_then(|v| v.as_str()) != Some("error") {
            continue;
        }
        if let Some(code) = msg.get("code").and_then(|c| c.get("code")).and_then(|c| c.as_str()) {
            *counts.entry(code.to_string()).or_default() += 1;
        }
    }
}

pub fn compute_delta_error_counts(
    baseline: &BTreeMap<String, usize>,
    after: &BTreeMap<String, usize>,
) -> BTreeMap<String, i64> {
    let mut out = BTreeMap::new();
    for key in baseline.keys().chain(after.keys()) {
        let base = *baseline.get(key).unwrap_or(&0) as i64;
        let new = *after.get(key).unwrap_or(&0) as i64;
        let delta = new - base;
        if delta != 0 {
            out.insert(key.clone(), delta);
        }
    }
    out
}

pub fn summarize_error_categories(
    messages: &[serde_json::Value],
) -> Vec<serde_json::Value> {
    let mut by_code: BTreeMap<String, (String, usize)> = BTreeMap::new();
    for msg in messages {
        if msg.get("level").and_then(|v| v.as_str()) != Some("error") {
            continue;
        }
        let code = msg
            .get("code")
            .and_then(|c| c.get("code"))
            .and_then(|c| c.as_str())
            .unwrap_or("unknown")
            .to_string();
        let desc = msg
            .get("message")
            .and_then(|m| m.as_str())
            .unwrap_or("")
            .to_string();
        let entry = by_code.entry(code).or_insert((desc.clone(), 0));
        entry.1 += 1;
        if entry.0.is_empty() && !desc.is_empty() {
            entry.0 = desc;
        }
    }
    by_code
        .into_iter()
        .map(|(code, (description, count))| {
            serde_json::json!({
                "code": code,
                "description": description,
                "count": count
            })
        })
        .collect()
}

